import{_ as e,o as a,c as d,a2 as i}from"./chunks/framework.il0noOp3.js";const m=JSON.parse('{"title":"WAF — enumerated source for the Sustainability Well-Architected Review","description":"","frontmatter":{},"headers":[],"relativePath":"frameworks/waf-sustainability-checklist.md","filePath":"frameworks/waf-sustainability-checklist.md"}'),r={name:"frameworks/waf-sustainability-checklist.md"};function o(n,t,s,c,l,u){return a(),d("div",null,[...t[0]||(t[0]=[i('<h1 id="waf-—-enumerated-source-for-the-sustainability-well-architected-review" tabindex="-1">WAF — enumerated source for the Sustainability Well-Architected Review <a class="header-anchor" href="#waf-—-enumerated-source-for-the-sustainability-well-architected-review" aria-label="Permalink to &quot;WAF — enumerated source for the Sustainability Well-Architected Review&quot;">​</a></h1><p><strong>Enumerated 2026-11-25. Verification method and limits are stated below — read them before quoting any coverage number from this page.</strong></p><p>Scout&#39;s <code>waf.sustainability.yaml</code> scores an estate against Microsoft&#39;s sustainability workload guidance, the scope of the <a href="https://learn.microsoft.com/en-us/assessments/f236012a-0070-45db-b94c-fe8de0799f38/" target="_blank" rel="noreferrer">Sustainability Well-Architected Review</a> assessment. The file is written against this page only, and every rule cites an item number from the tables below.</p><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Assessment</td><td><a href="https://learn.microsoft.com/en-us/assessments/f236012a-0070-45db-b94c-fe8de0799f38/" target="_blank" rel="noreferrer">Sustainability | Well-Architected Review</a> (30 minutes, multiple choice and multiple response; question text not published)</td></tr><tr><td>Framework version</td><td>Sustainability workload guidance on Microsoft Learn (unversioned; the extraction date is the version)</td></tr><tr><td>Extraction date</td><td>2026-11-25</td></tr><tr><td>Verification method</td><td>The workload index, the design methodology, the five per-pillar recommendation pages and the sustainable AI design page below were fetched in full with the Microsoft Learn MCP <code>microsoft_docs_fetch</code> tool on 2026-11-25. The assessment landing page was also fetched. The &quot;What is sustainability?&quot; overview page was not read. Every property an automated item reads was checked against the collect.json contract in <code>src/collect/Invoke-Collect.ps1</code>; ARM semantics come from those existing projections and were not re-checked against a live estate.</td></tr></tbody></table><h2 id="the-one-thing-this-enumeration-is-not" tabindex="-1">The one thing this enumeration is NOT <a class="header-anchor" href="#the-one-thing-this-enumeration-is-not" aria-label="Permalink to &quot;The one thing this enumeration is NOT&quot;">​</a></h2><p><strong>It is not Microsoft&#39;s question list.</strong> The assessment&#39;s questions are not published. The items below are <strong>Scout&#39;s</strong> reading of the guidance, one item per recommendation topic (or per automatable signal within a topic), and the <code>WAF-SUS-*</code> IDs are Scout&#39;s.</p><p>Two notes on the source:</p><ul><li>The sustainability workload index links its assessment as <code>a24b1079-29a4-4d22-b678-376e84884f76</code>; that page and <code>f236012a-0070-45db-b94c-fe8de0799f38</code> both render as &quot;Sustainability | Well-Architected Review&quot;. Scout cites the second, as requested.</li><li>Carbon emissions are not collected by Scout, so every emissions item (baseline, targets, SCI) is Manual. The cost-based items rest on Microsoft&#39;s own statement that cost is a practical proxy for sustainability.</li></ul><p>Sources:</p><ul><li>[IDX] <a href="https://learn.microsoft.com/azure/well-architected/sustainability/" target="_blank" rel="noreferrer">Sustainability workload documentation</a></li><li>[MTH] <a href="https://learn.microsoft.com/azure/well-architected/sustainability/sustainability-design-methodology" target="_blank" rel="noreferrer">Design methodology for sustainable workloads</a></li><li>[REL] <a href="https://learn.microsoft.com/azure/well-architected/sustainability/sustainability-reliability-recommendations" target="_blank" rel="noreferrer">Reliability recommendations</a></li><li>[SEC] <a href="https://learn.microsoft.com/azure/well-architected/sustainability/sustainability-security-recommendations" target="_blank" rel="noreferrer">Security recommendations</a></li><li>[COST] <a href="https://learn.microsoft.com/azure/well-architected/sustainability/sustainability-cost-optimization-recommendations" target="_blank" rel="noreferrer">Cost Optimization recommendations</a></li><li>[OPS] <a href="https://learn.microsoft.com/azure/well-architected/sustainability/sustainability-operational-excellence-recommendations" target="_blank" rel="noreferrer">Operational Excellence recommendations</a></li><li>[PERF] <a href="https://learn.microsoft.com/azure/well-architected/sustainability/sustainability-performance-efficiency-recommendations" target="_blank" rel="noreferrer">Performance Efficiency recommendations</a></li><li>[AI] <a href="https://learn.microsoft.com/azure/well-architected/sustainability/sustainable-ai-design" target="_blank" rel="noreferrer">Sustainable AI design for workloads</a></li></ul><h2 id="scope-an-estate-not-a-workload" tabindex="-1">Scope: an estate, not a workload <a class="header-anchor" href="#scope-an-estate-not-a-workload" aria-label="Permalink to &quot;Scope: an estate, not a workload&quot;">​</a></h2><p>Scout scans subscriptions, not one workload. An automated item reports on <strong>every</strong> resource of that type in the scanned scope. Idle and orphaned resources, autoscale coverage, Advisor findings and edge protections are what Scout can see; region choice, application efficiency and carbon accounting are not, and are Manual.</p><p>Automated items are <strong>gated</strong>: they run only when the relevant resources (or Advisor data, or governance data) exist, so an estate with none reports them Not assessed rather than passed. Items marked &quot;name heuristic&quot; match a policy assignment&#39;s display name and miss a differently named one.</p><h2 id="the-enumeration-—-67-items" tabindex="-1">The enumeration — 67 items <a class="header-anchor" href="#the-enumeration-—-67-items" aria-label="Permalink to &quot;The enumeration — 67 items&quot;">​</a></h2><h3 id="reliability-waf-sus-re-—-16-items" tabindex="-1">Reliability (WAF-SUS-RE) — 16 items <a class="header-anchor" href="#reliability-waf-sus-re-—-16-items" aria-label="Permalink to &quot;Reliability (WAF-SUS-RE) — 16 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>WAF-SUS-RE-01</td><td>Failure amplification is prevented (circuit breakers, throttling, graceful degradation, dependency isolation)</td><td>❌ Manual</td><td>REL · Prevent failure amplification</td></tr><tr><td>WAF-SUS-RE-02</td><td>Resiliency is matched to business requirements, and multi-region and failover capacity are justified</td><td>❌ Manual</td><td>REL · Design resiliency intentionally</td></tr><tr><td>WAF-SUS-RE-03</td><td>Backup, replication and retention strategies are reviewed against recovery needs</td><td>❌ Manual — backup policies attached</td><td>REL · Design resiliency intentionally; PERF · Reduce storage footprint</td></tr><tr><td>WAF-SUS-RE-04</td><td>Burst demand is smoothed with asynchronous processing, queues and batching</td><td>❌ Manual</td><td>REL · Stabilize demand to reduce waste</td></tr><tr><td>WAF-SUS-RE-05</td><td>No autoscale setting is switched off</td><td>✅ autoscale <code>enabled</code></td><td>REL · Stabilize demand; Factor sustainability into platform choices; COST · Reduce idle and baseline platform waste</td></tr><tr><td>WAF-SUS-RE-06</td><td>Standard, Premium and Isolated App Service plans are scaled by an enabled autoscale setting</td><td>✅ App Service plan → enabled autoscale setting</td><td>COST · Reduce idle and baseline platform waste; PERF · Balance with scalability needs</td></tr><tr><td>WAF-SUS-RE-07</td><td>Managed PaaS, serverless and containers are used where they fit, and platform versions are kept current</td><td>❌ Manual — virtual machines attached</td><td>REL · Factor sustainability into platform choices; COST · Reduce idle and baseline platform waste</td></tr><tr><td>WAF-SUS-RE-08</td><td>No unattached managed disks remain</td><td>✅ unattached disks</td><td>REL · Factor sustainability into platform choices (remove orphaned resources); COST · Reduce idle and baseline platform waste</td></tr><tr><td>WAF-SUS-RE-09</td><td>No public IP addresses are left unassociated</td><td>✅ unassociated public IPs</td><td>REL · Factor sustainability into platform choices (remove orphaned resources); COST · Reduce idle and baseline platform waste</td></tr><tr><td>WAF-SUS-RE-10</td><td>No snapshot outlives the disk it was taken from</td><td>✅ snapshot → source disk</td><td>COST · Control storage growth over time (remove stale data)</td></tr><tr><td>WAF-SUS-RE-11</td><td>No load balancer has an empty set of backend pools</td><td>✅ <code>backendPoolCount</code></td><td>REL · Factor sustainability into platform choices (remove zombie workloads); COST · Reduce idle and baseline platform waste</td></tr><tr><td>WAF-SUS-RE-12</td><td>No NAT gateway is attached to zero subnets</td><td>✅ <code>subnetCount</code></td><td>REL · Factor sustainability into platform choices (remove zombie workloads); COST · Reduce idle and baseline platform waste</td></tr><tr><td>WAF-SUS-RE-13</td><td>Non-production environments are shut down or scaled down when not in use</td><td>❌ Manual</td><td>REL · Factor sustainability into platform choices; COST · Reduce idle and baseline platform waste</td></tr><tr><td>WAF-SUS-RE-14</td><td>Spot VMs are used only for interrupt-tolerant workloads</td><td>❌ Manual</td><td>REL · Factor sustainability into platform choices; COST · Reduce idle and baseline platform waste</td></tr><tr><td>WAF-SUS-RE-15</td><td>Deployment regions weigh carbon intensity, latency and resiliency together</td><td>❌ Manual</td><td>REL · Factor sustainability into platform choices; COST · Use geography and timing deliberately</td></tr><tr><td>WAF-SUS-RE-16</td><td>Load testing and chaos engineering are proportionate, scheduled and scoped</td><td>❌ Manual — chaos experiments attached</td><td>REL · Run tests that provide meaningful resiliency validation</td></tr></tbody></table><h3 id="security-waf-sus-se-—-8-items" tabindex="-1">Security (WAF-SUS-SE) — 8 items <a class="header-anchor" href="#security-waf-sus-se-—-8-items" aria-label="Permalink to &quot;Security (WAF-SUS-SE) — 8 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>WAF-SUS-SE-01</td><td>Web application firewall policies run in Prevention mode</td><td>✅ policy <code>mode</code></td><td>SEC · Prevent malicious activity from driving unnecessary resource consumption</td></tr><tr><td>WAF-SUS-SE-02</td><td>Application Gateways have the web application firewall enabled</td><td>✅ <code>wafEnabled</code></td><td>SEC · Prevent malicious activity from driving unnecessary resource consumption</td></tr><tr><td>WAF-SUS-SE-03</td><td>Virtual networks are protected by Azure DDoS Network Protection</td><td>✅ virtual network <code>ddosEnabled</code></td><td>SEC · Prevent malicious activity from driving unnecessary resource consumption</td></tr><tr><td>WAF-SUS-SE-04</td><td>Rate limiting, throttling and identity-based access limit abusive usage</td><td>❌ Manual — API Management attached</td><td>SEC · Prevent malicious activity from driving unnecessary resource consumption</td></tr><tr><td>WAF-SUS-SE-05</td><td>Storage accounts deny public network access by default</td><td>✅ <code>networkDefaultDeny</code></td><td>SEC · Security hardening improves sustainability by reducing workload footprint</td></tr><tr><td>WAF-SUS-SE-06</td><td>SQL servers do not allow public network access</td><td>✅ <code>publicNetworkAccess</code></td><td>SEC · Security hardening improves sustainability by reducing workload footprint</td></tr><tr><td>WAF-SUS-SE-07</td><td>Security telemetry is filtered at the source and collected for a purpose</td><td>❌ Manual — data collection rules attached</td><td>SEC · Reduce security data collection and processing overhead</td></tr><tr><td>WAF-SUS-SE-08</td><td>Security controls sit close to traffic sources, and routing through central inspection is limited to traffic that needs it</td><td>❌ Manual — firewalls attached</td><td>SEC · Improve centralized network security efficiency</td></tr></tbody></table><h3 id="cost-optimization-waf-sus-co-—-10-items" tabindex="-1">Cost optimization (WAF-SUS-CO) — 10 items <a class="header-anchor" href="#cost-optimization-waf-sus-co-—-10-items" aria-label="Permalink to &quot;Cost optimization (WAF-SUS-CO) — 10 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>WAF-SUS-CO-01</td><td>Cost Management budgets exist to give workload owners accountability</td><td>✅ budget exists (estate-wide)</td><td>COST · Make cost visible and actionable</td></tr><tr><td>WAF-SUS-CO-02</td><td>High-impact Advisor cost recommendations are addressed</td><td>✅ Advisor cost, high impact</td><td>COST · Make cost visible and actionable; MTH · Measure and track carbon impact</td></tr><tr><td>WAF-SUS-CO-03</td><td>Advisor has no open finding of idle, unused or underutilized resources</td><td>✅ Advisor cost text match (any impact)</td><td>COST · Reduce idle and baseline platform waste; MTH · Apply a shared responsibility mindset</td></tr><tr><td>WAF-SUS-CO-04</td><td>Observability spend and telemetry retention are part of the optimization scope</td><td>❌ Manual — workspaces retaining over 90 days attached</td><td>COST · Make cost visible and actionable; Control storage growth over time</td></tr><tr><td>WAF-SUS-CO-05</td><td>Service tiers and reservations match actual usage</td><td>❌ Manual — reservations attached</td><td>COST · Reduce idle and baseline platform waste</td></tr><tr><td>WAF-SUS-CO-06</td><td>CI/CD and engineering workflows are proportionate to the change</td><td>❌ Manual</td><td>COST · Keep engineering workflows proportionate; Reduce idle and baseline platform waste</td></tr><tr><td>WAF-SUS-CO-07</td><td>Region and timing of execution are chosen deliberately, including lower-carbon regions and flexible batch windows</td><td>❌ Manual</td><td>COST · Use geography and timing deliberately; MTH · Build carbon-aware applications</td></tr><tr><td>WAF-SUS-CO-08</td><td>Cross-region replication and routing serve a clear workload need</td><td>❌ Manual — geo-replicated storage accounts attached</td><td>COST · Use geography and timing deliberately; Limit delivery-path amplification</td></tr><tr><td>WAF-SUS-CO-09</td><td>Storage tiers follow access patterns, and stale or duplicated data is removed on purpose</td><td>❌ Manual</td><td>COST · Control storage growth over time</td></tr><tr><td>WAF-SUS-CO-10</td><td>Cost is tracked per workload or feature, with explicit efficiency baselines for critical systems</td><td>❌ Manual</td><td>COST · Make cost visible and actionable; Reduce structural waste in the application layer</td></tr></tbody></table><h3 id="operational-excellence-waf-sus-oe-—-11-items" tabindex="-1">Operational excellence (WAF-SUS-OE) — 11 items <a class="header-anchor" href="#operational-excellence-waf-sus-oe-—-11-items" aria-label="Permalink to &quot;Operational excellence (WAF-SUS-OE) — 11 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>WAF-SUS-OE-01</td><td>A baseline of current carbon emissions exists for every workload and service</td><td>❌ Manual</td><td>OPS · Monitor and measure sustainability; MTH · Measure and track carbon impact</td></tr><tr><td>WAF-SUS-OE-02</td><td>Carbon reduction targets are defined for the workload and its components</td><td>❌ Manual</td><td>OPS · Monitor and measure sustainability</td></tr><tr><td>WAF-SUS-OE-03</td><td>A measurable metric such as the Software Carbon Intensity score is tracked alongside SLOs</td><td>❌ Manual</td><td>OPS · Monitor and measure sustainability; MTH · Measure and track carbon impact</td></tr><tr><td>WAF-SUS-OE-04</td><td>The impact of sustainability changes is recorded and assessed</td><td>❌ Manual</td><td>OPS · Monitor and measure sustainability</td></tr><tr><td>WAF-SUS-OE-05</td><td>Azure Policy assignments exist to drive consistent behaviour</td><td>✅ policy assignment exists (estate-wide)</td><td>OPS · Use policy to drive behavior to support sustainability</td></tr><tr><td>WAF-SUS-OE-06</td><td>A sustainability-focused policy initiative is assigned</td><td>✅ assignment named for sustainability or carbon (name heuristic)</td><td>OPS · Use policy to drive behavior to support sustainability</td></tr><tr><td>WAF-SUS-OE-07</td><td>A policy requires or inherits tags for sustainability reporting</td><td>✅ tag policy assignment (name heuristic)</td><td>OPS · Use policy to drive behavior to support sustainability</td></tr><tr><td>WAF-SUS-OE-08</td><td>Data lifecycle and telemetry-intake policies keep only necessary data</td><td>❌ Manual — data collection rules attached</td><td>OPS · Use policy to drive behavior to support sustainability</td></tr><tr><td>WAF-SUS-OE-09</td><td>Policy compliance is reviewed regularly for further optimization</td><td>❌ Manual</td><td>OPS · Use policy to drive behavior to support sustainability</td></tr><tr><td>WAF-SUS-OE-10</td><td>A sustainability community, training and shared guidance exist</td><td>❌ Manual</td><td>OPS · Build culture around sustainability; MTH · Evolve sustainability practices with the ecosystem</td></tr><tr><td>WAF-SUS-OE-11</td><td>Sustainability objectives sit in governance, reviews and KPIs, and good results are recognized</td><td>❌ Manual</td><td>OPS · Build culture around sustainability; MTH · Promote sustainability as a success measure</td></tr></tbody></table><h3 id="performance-efficiency-waf-sus-pe-—-12-items" tabindex="-1">Performance efficiency (WAF-SUS-PE) — 12 items <a class="header-anchor" href="#performance-efficiency-waf-sus-pe-—-12-items" aria-label="Permalink to &quot;Performance efficiency (WAF-SUS-PE) — 12 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>WAF-SUS-PE-01</td><td>API communication is efficient, throttled, cached and monitored</td><td>❌ Manual — API Management attached</td><td>PERF · Improve application efficiency; COST · Reduce structural waste in the application layer</td></tr><tr><td>WAF-SUS-PE-02</td><td>Rendering strategy and user interface are chosen for efficiency</td><td>❌ Manual</td><td>PERF · Improve application efficiency</td></tr><tr><td>WAF-SUS-PE-03</td><td>Workloads are profiled, with CPU and memory baselines and quality gates in deployment pipelines</td><td>❌ Manual</td><td>PERF · Optimize compute resources</td></tr><tr><td>WAF-SUS-PE-04</td><td>Specialized compute such as GPUs is evaluated where it improves efficiency</td><td>❌ Manual</td><td>PERF · Optimize compute resources</td></tr><tr><td>WAF-SUS-PE-05</td><td>CDN, caching and compression reduce network traffic</td><td>❌ Manual — CDN profiles attached</td><td>PERF · Reduce network traversal; COST · Limit delivery-path amplification</td></tr><tr><td>WAF-SUS-PE-06</td><td>Workloads and dependencies are placed close to users and to each other</td><td>❌ Manual</td><td>PERF · Reduce network traversal</td></tr><tr><td>WAF-SUS-PE-07</td><td>Storage is compressed, queries are optimized and data is aligned to access tiers</td><td>❌ Manual</td><td>PERF · Reduce storage footprint</td></tr><tr><td>WAF-SUS-PE-08</td><td>Service tiers match demand and dynamic scaling is preferred over fixed capacity</td><td>❌ Manual — App Service plans attached</td><td>PERF · Balance with scalability needs</td></tr><tr><td>WAF-SUS-PE-09</td><td>CI/CD pipelines cache build outputs</td><td>❌ Manual</td><td>PERF · Drive efficiency in deployments; COST · Keep engineering workflows proportionate</td></tr><tr><td>WAF-SUS-PE-10</td><td>Virtual machines use platform-orchestrated patching</td><td>✅ <code>patchMode</code></td><td>PERF · Use modern technology</td></tr><tr><td>WAF-SUS-PE-11</td><td>Legacy applications are identified and modernized to cloud-native or optimized PaaS</td><td>❌ Manual</td><td>PERF · Use modern technology</td></tr><tr><td>WAF-SUS-PE-12</td><td>Caches use Azure Managed Redis rather than the retiring Azure Cache for Redis</td><td>✅ cache <code>type</code></td><td>PERF · Use modern technology</td></tr></tbody></table><h3 id="sustainable-ai-design-waf-sus-ai-—-10-items" tabindex="-1">Sustainable AI design (WAF-SUS-AI) — 10 items <a class="header-anchor" href="#sustainable-ai-design-waf-sus-ai-—-10-items" aria-label="Permalink to &quot;Sustainable AI design (WAF-SUS-AI) — 10 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>WAF-SUS-AI-01</td><td>Model size is matched to the problem, favoring small language models where they suffice</td><td>❌ Manual — AI services accounts attached</td><td>AI · Model design recommendations</td></tr><tr><td>WAF-SUS-AI-02</td><td>Pretrained models and fine-tuning are preferred to training from scratch</td><td>❌ Manual</td><td>AI · Model design recommendations</td></tr><tr><td>WAF-SUS-AI-03</td><td>Training runs in a low-carbon region with carbon-aware scheduling</td><td>❌ Manual — ML workspaces attached</td><td>AI · Model design recommendations (training region); Data design recommendations (regional data strategy)</td></tr><tr><td>WAF-SUS-AI-04</td><td>Model and result caching avoid redundant computation</td><td>❌ Manual</td><td>AI · Model design recommendations</td></tr><tr><td>WAF-SUS-AI-05</td><td>Data is reused, filtered, sampled and cleaned before training, with efficient ingestion</td><td>❌ Manual</td><td>AI · Data design recommendations</td></tr><tr><td>WAF-SUS-AI-06</td><td>Storage, regional data placement and disaster recovery are optimized for energy</td><td>❌ Manual</td><td>AI · Data design recommendations</td></tr><tr><td>WAF-SUS-AI-07</td><td>Edge processing is considered where it cuts data movement</td><td>❌ Manual</td><td>AI · Data design recommendations</td></tr><tr><td>WAF-SUS-AI-08</td><td>Inference is deployed and scaled with carbon intensity in mind</td><td>❌ Manual</td><td>AI · Operational design recommendations</td></tr><tr><td>WAF-SUS-AI-09</td><td>Retraining is threshold-based, driven by model decay detection rather than a fixed frequency</td><td>❌ Manual</td><td>AI · Operational design recommendations</td></tr><tr><td>WAF-SUS-AI-10</td><td>Sustainability metrics sit in AI monitoring and MLOps, with controlled rollout and rollback</td><td>❌ Manual</td><td>AI · Operational design recommendations; OPS · Monitor and measure sustainability</td></tr></tbody></table><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Pillar lens</th><th>Items</th><th>Automated (✅)</th><th>Manual (❌)</th></tr></thead><tbody><tr><td>Reliability</td><td>16</td><td>7</td><td>9</td></tr><tr><td>Security</td><td>8</td><td>5</td><td>3</td></tr><tr><td>Cost optimization</td><td>10</td><td>3</td><td>7</td></tr><tr><td>Operational excellence</td><td>11</td><td>3</td><td>8</td></tr><tr><td>Performance efficiency</td><td>12</td><td>2</td><td>10</td></tr><tr><td>Sustainable AI design</td><td>10</td><td>0</td><td>10</td></tr><tr><td><strong>Total</strong></td><td><strong>67</strong></td><td><strong>20</strong></td><td><strong>47</strong></td></tr></tbody></table><p>Where an item says &quot;attached&quot;, Scout carries the matching resources as evidence on the Manual finding but does not score them.</p>',30)])])}const p=e(r,[["render",o]]);export{m as __pageData,p as default};
